SELECT FROM diary WHERE user_id = #{userId}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY created_at DESC

SELECT FROM diary WHERE user_id = #{userId}
AND LOWER(CAST(tags AS CHAR)) LIKE CONCAT('%"', LOWER(#{tag}), '"%')
ORDER BY created_at DESC
